namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public string DepartmentCode { get; set; } = string.Empty;
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.", IsFeatured = true, DepartmentName = "Computer Science", DepartmentCode = "CS" },
            new() { Id = 2, DepartmentId = 1, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez specializes in algorithm optimization and competitive programming. He has coached multiple ICPC finalist teams.", IsFeatured = true, DepartmentName = "Computer Science", DepartmentCode = "CS" },
            new() { Id = 3, DepartmentId = 1, Code = "CS 310", Title = "Database Systems", Description = "Design and implementation of database management systems. Covers relational algebra, SQL, normalization, transaction processing, and NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:30 PM", InstructorName = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez spent 10 years at Oracle before joining academia. Her research focuses on distributed database systems.", IsFeatured = false, DepartmentName = "Computer Science", DepartmentCode = "CS" },
            new() { Id = 4, DepartmentId = 2, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator with a passion for making calculus accessible to all students.", IsFeatured = true, DepartmentName = "Mathematics", DepartmentCode = "MATH" },
            new() { Id = 5, DepartmentId = 2, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues and eigenvectors. Applications to computer graphics and data science.", Credits = 3, Schedule = "Tue/Thu 1:00–2:30 PM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research bridges pure mathematics and machine learning applications.", IsFeatured = false, DepartmentName = "Mathematics", DepartmentCode = "MATH" },
            new() { Id = 6, DepartmentId = 3, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes hands-on laboratory sessions with modern equipment.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM, Lab: Thu 2:00–4:00 PM", InstructorName = "Dr. Alan Park", InstructorBio = "Dr. Park is a former NASA researcher with expertise in classical mechanics and astrophysics.", IsFeatured = true, DepartmentName = "Physics", DepartmentCode = "PHYS" },
            new() { Id = 7, DepartmentId = 3, Code = "PHYS 220", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 3, Schedule = "Tue/Thu 9:00–10:30 AM", InstructorName = "Dr. Lisa Nguyen", InstructorBio = "Dr. Nguyen's research focuses on quantum electrodynamics and photonics.", IsFeatured = false, DepartmentName = "Physics", DepartmentCode = "PHYS" },
            new() { Id = 8, DepartmentId = 4, Code = "ENG 101", Title = "English Composition", Description = "Develop critical reading and writing skills. Focus on argumentative essays, research papers, and rhetorical analysis.", Credits = 3, Schedule = "Mon/Wed 9:00–10:30 AM", InstructorName = "Prof. David Thompson", InstructorBio = "Prof. Thompson is a published author and has taught composition for over 20 years.", IsFeatured = false, DepartmentName = "English", DepartmentCode = "ENG" },
            new() { Id = 9, DepartmentId = 4, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, including works by Twain, Fitzgerald, Morrison, and others.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:30 PM", InstructorName = "Dr. Angela Brooks", InstructorBio = "Dr. Brooks specializes in 20th-century American fiction and has received multiple teaching excellence awards.", IsFeatured = false, DepartmentName = "English", DepartmentCode = "ENG" },
            new() { Id = 10, DepartmentId = 5, Code = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from antiquity through the Renaissance, examining political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Michael Foster", InstructorBio = "Dr. Foster is an archaeologist and historian who has led excavations across the Mediterranean.", IsFeatured = false, DepartmentName = "History", DepartmentCode = "HIST" },
            new() { Id = 11, DepartmentId = 5, Code = "HIST 315", Title = "Modern European History", Description = "Europe from the French Revolution to the present day. Covers industrialization, world wars, and the formation of the European Union.", Credits = 3, Schedule = "Tue/Thu 3:00–4:30 PM", InstructorName = "Dr. Catherine Bell", InstructorBio = "Dr. Bell is a specialist in modern European political history with a focus on diplomatic relations.", IsFeatured = false, DepartmentName = "History", DepartmentCode = "HIST" }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.DepartmentName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollment(EnrollmentRequest request) => _enrollments.Add(request);
}

